import { useState } from "react";

export const SliderImage = ({ images }) => {
    const [sliderPosition, setSliderPosition] = useState(50);
    const [isDragging, setIsDragging] = useState(false);

    // Hem Mouse hem Touch için koordinat hesaplayan yardımcı fonksiyon
    const getPositionX = (event) => {
        return event.type.includes('touch') 
            ? event.touches[0].clientX 
            : event.clientX;
    };

    const handleMove = (event) => {
        if (!isDragging) return;

        const rect = event.currentTarget.getBoundingClientRect();
        const clientX = getPositionX(event);
        
        const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
        const percent = Math.max(0, Math.min((x / rect.width) * 100, 100));

        setSliderPosition(percent);
    };

    const handleStart = () => setIsDragging(true);
    const handleEnd = () => setIsDragging(false);

    return (
        <div 
            className="w-full h-full relative" 
            onMouseUp={handleEnd}
            onTouchEnd={handleEnd} // Mobil bitiş
        >
            <div
                className="relative w-full h-full m-auto overflow-hidden select-none touch-none" // touch-none kaydırmayı engeller
                onMouseMove={handleMove}
                onMouseDown={handleStart}
                onTouchMove={handleMove} // Mobil hareket
                onTouchStart={handleStart} // Mobil başlangıç
            >
                <img
                    alt="Before"
                    className="w-full h-full object-cover"
                    draggable={false}
                    src={images[0]}
                />

                <div
                    className="absolute top-0 left-0 right-0 w-full h-full m-auto overflow-hidden select-none"
                    style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}
                >
                    <img
                        className="w-full h-full object-cover"
                        draggable={false}
                        src={images[1]}
                        alt="After"
                    />
                </div>
                
                {/* Kaydırıcı Çizgisi ve Butonu */}
                <div
                    className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize"
                    style={{ left: `calc(${sliderPosition}% - 1px)` }}
                >
                    <div className="bg-white absolute rounded-full h-6 w-6 -left-[10px] top-1/2 -translate-y-1/2 shadow-lg flex items-center justify-center">
                        <span className="text-gray-400 text-xs">||</span>
                    </div>
                </div>
            </div>
        </div>
    );
};