import React, { useEffect, useState } from 'react'
import { Breadcrumbs } from './LocalComponents/Breadcrumbs'
import { CategoryHeader } from './LocalComponents/CategoryHeader'
import { Images } from './LocalComponents/Images'
import { useParams } from 'react-router-dom'
import { categories } from '../../data'
import { useImagesStore } from '../../store/userImagesStore'
import { ImagePagination } from './LocalComponents/ImagePagination'

const breadcrump = [
    {
        value: "Home",
        link: "/"
    },
    {
        value: "Portfolio",
        link: "/"
    }
]


export const CategoryPage = () => {
    const {category} = useParams()
    const [categoryData, setCategoryData] = useState(categories.filter(item=>category === item.to)[0])
    
    const {openModal} = useImagesStore()

    useEffect(()=>{
        setCategoryData(categories.filter(item=>category === item.to)[0])
    },[category])


    return (
        <main className="flex-grow w-full px-4 md:px-10 lg:px-40 py-8 flex justify-center">
            <div className="flex flex-col max-w-[1200px] w-full gap-10">
                <Breadcrumbs items={[...breadcrump,{value:categoryData.title}]}/>
                <CategoryHeader headerInfo={{title:categoryData.title, description:categoryData.description}}/>
                {categoryData.projects?.map((item,index)=>{
                    return(
                        <Images key={index} project={item}/>
                    )
                })}
                {openModal &&
                    <ImagePagination/>
                }
            </div>
        </main>
    )
}
