import React from 'react'
import { HiMiniMagnifyingGlassPlus } from "react-icons/hi2";
import { useImagesStore } from '../../../store/userImagesStore';

export const Images = ({project}) => {
    const {setOpenModal, setImageData, setIndex, productType, setProductType} = useImagesStore();

    const handleOpenModal = (index) => {
        setIndex(index);
        setOpenModal(true);
        if(productType !== project.projectName){
            setImageData([...project.beforeImages, ...project.afterImages]);
            setProductType(project.projectName);
        }
    }
    return (
        <section className="flex flex-col gap-6 bg-surface-dark/30 rounded-2xl p-6 md:p-8 border border-[#234248]">
            <div className="flex items-center justify-between">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-2 text-primary/80 text-xs font-bold uppercase tracking-widest">
                        <span className="material-symbols-outlined text-sm">landscape</span>
                        {project?.projectName}
                    </div>
                    <h2 className="text-white text-2xl font-bold leading-tight">{project?.name}</h2>
                </div>
            </div>
            <div className="flex flex-col gap-3">
                <div className="flex items-center gap-2 px-1">
                    <span className="material-symbols-outlined text-[#ef4444] text-xl">history</span>
                    <h3 className="text-white/70 text-sm font-bold uppercase tracking-wide">Before / Düzenlenmemiş</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    {project.beforeImages.map((item,index)=>{
                        return (
                            <div key={index} className="group relative aspect-[1/1] overflow-hidden rounded-xl bg-gray-800">
                                <div className="absolute inset-0 bg-contain bg-no-repeat bg-center" data-alt="Product Image" style={{ backgroundImage: `url('${item}')`}}></div>
                                <HiMiniMagnifyingGlassPlus className='absolute top-0 right-0 w-7 h-7 m-2 cursor-pointer' onClick={()=>handleOpenModal(index)}/>
                            </div>
                        )
                    })}
                </div>
            </div>
            <div className="flex justify-center -my-2 relative z-10">
                <div className="flex bg-[#234248] rounded-full p-1.5 border-4 border-background-dark">
                    <span className="material-symbols-outlined text-[#92c0c9]">arrow_downward</span>
                </div>
            </div>
            <div className="flex flex-col gap-3">
                <div className="flex items-center gap-2 px-1">
                    <span className="material-symbols-outlined text-primary text-xl">auto_fix_high</span>
                    <h3 className="text-primary text-sm font-bold uppercase tracking-wide">After / Düzenlenmiş</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    {project.afterImages.map((item,index)=>{
                        return (
                            <div key={index} className="group relative aspect-[1/1] overflow-hidden rounded-xl shadow-lg shadow-black/50 ring-1 ring-primary/20 hover:ring-primary transition-all duration-300">
                                <div className="absolute inset-0 bg-contain bg-no-repeat bg-center transform group-hover:scale-105 transition-transform duration-700" data-alt="Edited vibrant photo of misty green mountains with high contrast" style={{ backgroundImage: `url('${item}')`}}></div>
                                <HiMiniMagnifyingGlassPlus className='absolute top-0 right-0 w-7 h-7 m-2 cursor-pointer' onClick={()=>handleOpenModal(project.beforeImages.length + index)}/>
                            </div>
                        )
                    })}
                </div>
            </div>
        </section>
    )
}
