import { create } from 'zustand'

export const useImagesStore = create((set,get) => ({
    openModal: false,
    index: 0,
    productType: '',
    imageData: [],

    setOpenModal: (value) => set(() => ({ openModal: value })),
    setImageData:  (imageData) => {
        set(() => ({ imageData }))
    },
    setIndex: (index) => set(() => ({ index })),
    setProductType: (productType) => set(() => ({ productType })),
    next: () => {
        const { imageData, index } = get();
        if (imageData && index < imageData.length - 1) {
            set((state) => ({ index: state.index + 1 }))
        }else{
            set((state) => ({ index: 0 }))
        }
    },
    prev: () => {
        const { imageData, index } = get();
        if (imageData && index !== 0) {
            set((state) => ({ index: state.index - 1 }))
        }else{
            set((state) => ({ index: imageData.length - 1 }))
        }
    },
}))