import { useEffect } from 'react';
import { useImagesStore } from '../../../store/userImagesStore'
import { IoMdClose } from "react-icons/io";
import { IoChevronBack, IoChevronForward } from 'react-icons/io5'

export const ImagePagination = () => {
    const {setOpenModal, imageData, index, next, prev} = useImagesStore()

    useEffect(() => {
        // Klavye olayını yakalayan fonksiyon
        const handleKeyDown = (event) => {
            if (event.key === 'Escape') {
                handleClosePaggination();
            }
        };

        window.addEventListener('keydown', handleKeyDown);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, []); 
    
    const handleClosePaggination = () => {
        setOpenModal(false); 
    }
    return(
         <div className="w-full h-screen bg-gray-950/90 fixed top-0 left-0 z-50">
            <div className='relative w-full h-screen flex items-center justify-center'>
                <div className='rounded-full hover:bg-black bg-black/50 p-2' onClick={prev}><IoChevronBack className='w-6 h-6 cursor-pointer'/></div>
                    <div className='relative w-full h-screen flex items-center justify-center max-w-[90%] max-h-[80%] px-6'>
                        <img className='w-full h-full object-contain' src={imageData[index]} alt={"paggination_"+index}/>
                    </div>
                <div className='rounded-full hover:bg-black bg-black/50 p-2' onClick={next}><IoChevronForward className='w-6 h-6 cursor-pointer'/></div>
            </div>
            <IoMdClose className='absolute top-0 right-0 w-7 h-7 m-2 cursor-pointer' onClick={()=>setOpenModal(false)}/>
        </div>
    )
}